# Constantes físicas
#
# PERMISSIVIDADE_VACUO: a planilha original (Calc!E7 = Principal!G26*1E-9/(36*PI()))
# usa a aproximação clássica de engenharia eps0 ~= (1/(36*pi))*10^-9 F/m = 8.841941282883075e-12 F/m,
# e NÃO o valor CODATA de precisão (8.8541878128e-12 F/m). A diferença é de ~0,14% e se propaga a
# C, Zo, Ro, gamma e SIL. Mantido igual à planilha para fidelidade de metodologia (REGRA FUNDAMENTAL
# do projeto: não substituir por formulação "mais precisa" sem autorização). Validado por comparação
# Excel x Python no caso-exemplo (Tulip 336 CA, estrutura 3, l=100km) — ver testes.
PERMISSIVIDADE_VACUO = 1e-9 / (36 * 3.141592653589793)  # F/m — aproximação usada na planilha original
PERMISSIVIDADE_VACUO_CODATA = 8.8541878128e-12  # F/m — valor de precisão (referência, não usado nos cálculos)
PERMEABILIDADE_VACUO = 4e-7 * 3.141592653589793  # H/m (mu0)
VELOCIDADE_LUZ = 299792458.0  # m/s

# Limite de referência (regra prática de engenharia) para campo elétrico crítico
# de disrupção do ar (efeito corona), conforme literatura clássica (Peek, ar seco a 25°C, 76cmHg):
# Ecrit ~= 21.1 kV/cm (gradiente crítico disruptivo do ar). PREMISSA NÃO IDENTIFICADA NA PLANILHA
# — a planilha original calcula apenas o campo elétrico superficial (Calc!H15), sem comparar
# a um limite. Valor abaixo incluído apenas como referência informativa opcional no relatório.
CAMPO_ELETRICO_CRITICO_REFERENCIA_KV_CM = 21.1

